        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def comps(g,bg,conn=8):
    g=np.array(g); H,W=g.shape
    l,n=ndlabel(g!=bg)
    res=[]
    for i in range(1,n+1):
        mask=(l==i)
        pos=np.argwhere(mask)
        colset=collections.Counter([int(x) for x in g[pos].flatten()])
        main=max(colset,key=lambda c:colset[c])
        res.append({
            'label':i,'color':main,'size':len(pos),'colors':dict(colset),
            'shape':tuple(map(tuple,pos-pos[0])),'bbox':(pos[:,0].min(),pos[:,1].min()),'extent':(pos[:,0].max()-pos[:,0].min()+1,pos[:,1].max()-pos[:,1].min()+1)
        })
    return res

