        if any(p in ch for p in pts):
            print("   ",o['label'],'color',o['color'],'size',o['size'],'shape',o['shape'])

import numpy as np, collections, json
from scipy.ndimage import label as ndlabel

def objs(g,bg):
    g=np.array(g); H,W=g.shape
    lab,nn=ndlabel(g!=bg)
    out=[]
    for i in range(1,nn+1):
        m=(lab==i); pos=np.argwhere(m)
        cc=collections.Counter([int(x) for x in g[pos].flatten()])
        c=int(cc.most_common(1)[0][0])
        sh=tuple(map(tuple,pos-pos[0]))
        out.append({'l':i,'c':c,'n':len(pos),'sh':sh,'ext':(pos[:,0].max()-pos[:,0].min()+1,pos[:,1].max()-pos[:,1].min()+1)})
    return out

def report(name,a,b,bg):
    ch=set(zip(*np.where(a!=b)))
    oa=objs(a,bg); ob=objs(b,bg)
    di={}
    d,_=ndlabel(a); D={},{} 
    # match by extent & position overlap
    for o in oa:
        pts={(p[0],p[1]) for p in np.argwhere(d==o['l'])}
        inter=len(pts&ch)
        if inter:
            di[o['l']]={'in':o,'out':next((obj for obj in ob if len(set(np.argwhere(ndlabel(b)==obj['l']))&ch)>0),None)}
    print("=== %s bg=%d changes=%d ==="% (name,bg,len(ch)))
