        o=dd['in']; print(" changed comp color%o size%d shape%s extent%s"% (o['c'],o['n'],o['sh'][0] if o['sh'] else '',o['ext']))
    # list other objects for context
    print(" other in-comps:",[ (o['c'],o['n'],o['sh']) for o in oa if o['l'] not in di])
    print(" other out-comps:",[ (o['c'],o['n'],o['sh']) for o in ob if True ])

