def comps(g,bgcol=None):
    H,W=len(g),len(g[0])
    cnt=collections.Counter(int(x) for row in g for x in row)
    bgcol=bgcol or cnt.most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bgcol and not seen[r][c]:
                stack=[(r,c)]; seen[r][c]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]!=bgcol:
                            seen[ny][nx]=True; stack.append((ny,nx))
                base=(min(p[0] for p in cells),min(p[1] for p in cells))
                norm=tuple(sorted((p[0]-base[0],p[1]-base[1]) for p in cells))
                col=collections.Counter(int(g[y][x]) for y,x in cells).most_common(1)[0][0]
                out.append({'c':col,'cells':set(cells),'norm':norm})
    return out

