def colcomps(g,bgcol):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bgcol and not seen[r][c]:
                st=[(r,c)]; seen[r][c]=True; cl=[]
                while st:
                    y,x=st.pop(); cl.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==g[y][x] and g[ny][nx]!=bgcol:
                            seen[ny][nx]=True; st.append((ny,nx))
                ba=(min(p[0] for p in cl),min(p[1] for p in cl))
                norm=tuple(sorted((p[0]-ba[0],p[1]-ba[1]) for p in cl))
                out.append({'cells':cl,'color':g[y][x],'norm':norm,'size':len(cl),'bbox':(max(p[0] for p in cl)-ba[0]+1,max(p[1] for p in cl)-ba[1]+1)})
    return out

